import { existsSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { describe, expect, it } from "vitest";
import { ALL_SECTIONS } from "../src/types";
import { parseParams } from "../src/params";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
// theme.ts depends on src/themes.json, which is generated by a parallel agent
// (scripts/port-themes.ts). Gate the end-to-end "junk theme -> default" assertion on its
// presence so this file stays green even before that generation step has run; the
// integrator's full suite run will exercise it once themes.json exists.
const themesJsonExists = existsSync(path.resolve(__dirname, "../src/themes.json"));

describe("parseParams defaults", () => {
  it("returns ALL_SECTIONS, default theme, and svg output for an empty query", () => {
    const params = parseParams({});
    expect(params.sections).toEqual(ALL_SECTIONS);
    expect(params.sections).toEqual(["profile", "solved", "streak", "skills", "languages", "heatmap"]);
    expect(params.theme).toBe("default");
    expect(params.hideBorder).toBe(false);
    expect(params.transparent).toBe(false);
    expect(params.disableAnimations).toBe(false);
    expect(params.shortNumbers).toBe(false);
    expect(params.borderRadius).toBe(4.5);
    expect(params.colorOverrides).toEqual({});
    expect(params.output).toBe("svg");
  });

  it("defaults in languages (part of the default section set)", () => {
    const params = parseParams({});
    expect(params.sections).toContain("languages");
  });
});

describe("sections parsing", () => {
  it("filters junk, dedupes, and orders canonically: heatmap,bogus,PROFILE -> [profile, heatmap]", () => {
    const params = parseParams({ sections: "heatmap,bogus,PROFILE" });
    expect(params.sections).toEqual(["profile", "heatmap"]);
  });

  it("dedupes repeats and honors canonical order regardless of input order", () => {
    const params = parseParams({ sections: "heatmap,profile,solved,profile,heatmap" });
    expect(params.sections).toEqual(["profile", "solved", "heatmap"]);
  });

  it("includes languages only when explicitly requested", () => {
    const params = parseParams({ sections: "profile,solved,skills,languages" });
    expect(params.sections).toEqual(["profile", "solved", "skills", "languages"]);
  });

  it("falls back to ALL_SECTIONS when every token is invalid", () => {
    const params = parseParams({ sections: "bogus,junk,nope" });
    expect(params.sections).toEqual(ALL_SECTIONS);
  });

  it("falls back to ALL_SECTIONS for an empty string", () => {
    const params = parseParams({ sections: "" });
    expect(params.sections).toEqual(ALL_SECTIONS);
  });

  it("takes the first value of an array-valued sections param", () => {
    const params = parseParams({ sections: ["heatmap", "profile"] });
    expect(params.sections).toEqual(["heatmap"]);
  });
});

describe("theme name normalization", () => {
  it("lowercases and converts underscores to dashes", () => {
    expect(parseParams({ theme: "GitHub_Dark" }).theme).toBe("github-dark");
  });

  it("defaults to 'default' when absent or blank", () => {
    expect(parseParams({}).theme).toBe("default");
    expect(parseParams({ theme: "   " }).theme).toBe("default");
  });

  it("takes the first value of an array-valued theme param", () => {
    expect(parseParams({ theme: ["radical", "dracula"] }).theme).toBe("radical");
  });

  (themesJsonExists ? it : it.skip)(
    "junk theme names resolve to the default theme's colors via theme.ts",
    async () => {
      const { resolveTheme } = await import("../src/theme");
      const params = parseParams({ theme: "TotallyBogus_Theme!!" });
      const resolved = resolveTheme(params.theme, params.colorOverrides, params.hideBorder);
      const defaultResolved = resolveTheme("default", {}, false);
      expect(resolved).toEqual(defaultResolved);
    },
  );
});

describe("boolean flags", () => {
  it("require the exact string 'true'", () => {
    expect(parseParams({ hide_border: "true" }).hideBorder).toBe(true);
    expect(parseParams({ hide_border: "1" }).hideBorder).toBe(false);
    expect(parseParams({ hide_border: "TRUE" }).hideBorder).toBe(false);
    expect(parseParams({ hide_border: "yes" }).hideBorder).toBe(false);
    expect(parseParams({ disable_animations: "true" }).disableAnimations).toBe(true);
    expect(parseParams({ short_numbers: "true" }).shortNumbers).toBe(true);
  });
});

describe("border_radius", () => {
  it("parses a plain float", () => {
    expect(parseParams({ border_radius: "10" }).borderRadius).toBe(10);
    expect(parseParams({ border_radius: "12.5" }).borderRadius).toBe(12.5);
  });

  it("falls back to 4.5 when missing or non-finite", () => {
    expect(parseParams({}).borderRadius).toBe(4.5);
    expect(parseParams({ border_radius: "abc" }).borderRadius).toBe(4.5);
    expect(parseParams({ border_radius: "" }).borderRadius).toBe(4.5);
  });

  it("clamps to [0, 60]", () => {
    expect(parseParams({ border_radius: "-5" }).borderRadius).toBe(0);
    expect(parseParams({ border_radius: "999" }).borderRadius).toBe(60);
  });

  it("survives an injection-shaped value by parsing its numeric prefix (4.5 or fallback)", () => {
    // border_radius=4.5%22%20onload=alert(1) decoded by the query layer to: 4.5" onload=alert(1)
    const result = parseParams({ border_radius: '4.5" onload=alert(1)' }).borderRadius;
    expect(result === 4.5 || result === DEFAULT_FALLBACK).toBe(true);
  });
});

const DEFAULT_FALLBACK = 4.5;

describe("color override injection resistance", () => {
  it("rejects a javascript: URL disguised as a background value", () => {
    const params = parseParams({ background: "url(javascript:alert(1))" });
    expect(params.colorOverrides.background).toBeUndefined();
  });

  it("rejects garbage for a non-gradient key", () => {
    const params = parseParams({ ring: "'; alert(1); '" });
    expect(params.colorOverrides.ring).toBeUndefined();
  });

  it("accepts valid 6-digit hex and prefixes with #", () => {
    const params = parseParams({ ring: "39D353" });
    expect(params.colorOverrides.ring).toBe("#39D353");
  });

  it("accepts valid hex already prefixed with #", () => {
    const params = parseParams({ ring: "#39D353" });
    expect(params.colorOverrides.ring).toBe("#39D353");
  });

  it("accepts 3/4/8-digit hex forms", () => {
    expect(parseParams({ ring: "#abc" }).colorOverrides.ring).toBe("#abc");
    expect(parseParams({ ring: "#abcd" }).colorOverrides.ring).toBe("#abcd");
    expect(parseParams({ ring: "#aabbccdd" }).colorOverrides.ring).toBe("#aabbccdd");
  });

  it("rejects malformed hex lengths (5 or 7 chars)", () => {
    expect(parseParams({ ring: "#abcde" }).colorOverrides.ring).toBeUndefined();
    expect(parseParams({ ring: "abcdefa" }).colorOverrides.ring).toBeUndefined();
  });

  it("accepts a named CSS color, case-insensitively, stored lowercase", () => {
    expect(parseParams({ ring: "CornflowerBlue" }).colorOverrides.ring).toBe("cornflowerblue");
    expect(parseParams({ dates: "red" }).colorOverrides.dates).toBe("red");
  });

  it("rejects an unknown color name", () => {
    expect(parseParams({ ring: "notarealcolor" }).colorOverrides.ring).toBeUndefined();
  });

  it("accepts a gradient string for background only", () => {
    const params = parseParams({ background: "35,4158D0,C850C0,FFCC70" });
    expect(params.colorOverrides.background).toBe("35,4158D0,C850C0,FFCC70");
  });

  it("rejects a gradient-shaped string for a non-background key", () => {
    const params = parseParams({ ring: "35,4158D0,C850C0,FFCC70" });
    expect(params.colorOverrides.ring).toBeUndefined();
  });

  it("ignores unrecognized query keys entirely (no prototype pollution surface)", () => {
    const params = parseParams({ __proto__: "haxx", constructor: "haxx" } as unknown as Record<
      string,
      string
    >);
    expect(params.colorOverrides).toEqual({});
  });
});

describe("transparent param", () => {
  it("forces colorOverrides.background to #0000", () => {
    const params = parseParams({ transparent: "true" });
    expect(params.transparent).toBe(true);
    expect(params.colorOverrides.background).toBe("#0000");
  });

  it("wins over an explicit valid background param", () => {
    const params = parseParams({ transparent: "true", background: "39D353" });
    expect(params.colorOverrides.background).toBe("#0000");
  });

  it("wins over an explicit invalid background param too", () => {
    const params = parseParams({ transparent: "true", background: "url(javascript:x)" });
    expect(params.colorOverrides.background).toBe("#0000");
  });

  it("leaves background untouched when transparent is absent/false", () => {
    const params = parseParams({ background: "39D353" });
    expect(params.colorOverrides.background).toBe("#39D353");
  });

  it("combines freely with hide_border and border_radius (independent fields)", () => {
    const params = parseParams({
      transparent: "true",
      hide_border: "true",
      border_radius: "20",
    });
    expect(params.colorOverrides.background).toBe("#0000");
    expect(params.hideBorder).toBe(true);
    expect(params.borderRadius).toBe(20);
  });
});

describe("top_skills / top_langs", () => {
  it("default to 12 when absent", () => {
    const params = parseParams({});
    expect(params.topSkills).toBe(12);
    expect(params.topLangs).toBe(12);
  });

  it("parses a valid in-range value", () => {
    expect(parseParams({ top_skills: "3" }).topSkills).toBe(3);
    expect(parseParams({ top_langs: "5" }).topLangs).toBe(5);
  });

  it("clamps 0 up to the minimum of 1", () => {
    expect(parseParams({ top_skills: "0" }).topSkills).toBe(1);
    expect(parseParams({ top_langs: "0" }).topLangs).toBe(1);
  });

  it("clamps a negative value up to 1", () => {
    expect(parseParams({ top_skills: "-5" }).topSkills).toBe(1);
  });

  it("clamps values above 12 down to 12", () => {
    expect(parseParams({ top_skills: "99" }).topSkills).toBe(12);
    expect(parseParams({ top_langs: "99" }).topLangs).toBe(12);
  });

  it("falls back to 12 for non-numeric junk", () => {
    expect(parseParams({ top_skills: "junk" }).topSkills).toBe(12);
    expect(parseParams({ top_langs: "junk" }).topLangs).toBe(12);
  });

  it("takes the first value of an array-valued param", () => {
    expect(parseParams({ top_skills: ["3", "7"] }).topSkills).toBe(3);
  });
});

describe("output type", () => {
  it("defaults to svg", () => {
    expect(parseParams({}).output).toBe("svg");
  });

  it("switches to json only for the exact value 'json'", () => {
    expect(parseParams({ type: "json" }).output).toBe("json");
    expect(parseParams({ type: "JSON" }).output).toBe("svg");
    expect(parseParams({ type: "xml" }).output).toBe("svg");
  });
});
